import{_ as t,o as s,c as a,ag as i}from"./chunks/framework.BbSdnUwJ.js";const k=JSON.parse('{"title":"Drive types","description":"What each chassis type needs, what the base can do, and which controller and navigation settings the targets emit for it.","frontmatter":{"title":"Drive types","description":"What each chassis type needs, what the base can do, and which controller and navigation settings the targets emit for it."},"headers":[],"relativePath":"guide/advanced/drive-types.md","filePath":"guide/advanced/drive-types.md"}'),d={name:"guide/advanced/drive-types.md"};function n(h,e,o,r,l,c){return s(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="drive-types" tabindex="-1">Drive types <a class="header-anchor" href="#drive-types" aria-label="Permalink to &quot;Drive types&quot;">​</a></h1><p>The chassis type decides how the base drives. It fixes the wheel mounts a program must fill, what the base can do, and what the targets emit to drive it.</p><table tabindex="0"><thead><tr><th>Chassis type</th><th>Wheels</th><th>Driven</th><th>Steered</th><th>Spins in place</th><th>Holonomic</th><th>Controller</th></tr></thead><tbody><tr><td><code>Diff_two_caster</code></td><td>2 <code>Standard</code>, a caster</td><td>both</td><td>none</td><td>yes</td><td>no</td><td><code>diff_drive_controller</code></td></tr><tr><td><code>Diff_drive</code></td><td>4 <code>Standard</code></td><td>all</td><td>none</td><td>yes</td><td>no</td><td><code>diff_drive_controller</code>, two wheels a side</td></tr><tr><td><code>Mecanum_four_wheel</code></td><td>4 <code>Mecanum</code></td><td>all</td><td>none</td><td>yes</td><td>yes</td><td><code>mecanum_drive_controller</code></td></tr><tr><td><code>Omni_drive</code></td><td>4 <code>Omni_wheel</code></td><td>all</td><td>none</td><td>yes</td><td>yes</td><td>the runtime&#39;s omni drive</td></tr><tr><td><code>Omni_three_wheel</code></td><td>3 <code>Omni_wheel</code></td><td>all</td><td>none</td><td>yes</td><td>yes</td><td>the runtime&#39;s omni drive</td></tr><tr><td><code>Tricycle</code></td><td>3 <code>Standard</code></td><td>front</td><td>front</td><td>no</td><td>no</td><td><code>tricycle_controller</code></td></tr><tr><td><code>Ackermann</code></td><td>4 <code>Standard</code></td><td>rear</td><td>front pair</td><td>no</td><td>no</td><td><code>ackermann_steering_controller</code></td></tr></tbody></table><p>Every base takes <code>geometry_msgs/msg/TwistStamped</code> on <code>/cmd_vel</code> and publishes odometry on <code>/odom</code>, whatever its controller. The controller&#39;s kinematics, wheel radius, track and wheelbase, come from the placed wheels, not from numbers you type.</p><h2 id="what-the-task-may-ask" tabindex="-1">What the task may ask <a class="header-anchor" href="#what-the-task-may-ask" aria-label="Permalink to &quot;What the task may ask&quot;">​</a></h2><p><code>Spin</code> needs a base that turns in place, and <code>Strafe</code> a holonomic one. The rules <code>kinematics.spin_supported</code> and <code>kinematics.strafe_supported</code> check the task against the base at compile time.</p><h2 id="two-wheel-and-skid-steer-bases" tabindex="-1">Two-wheel and skid-steer bases <a class="header-anchor" href="#two-wheel-and-skid-steer-bases" aria-label="Permalink to &quot;Two-wheel and skid-steer bases&quot;">​</a></h2><p>A two-wheel base turns by driving its wheels at different speeds; its caster only supports it. A skid-steer base drags its wheels sideways to turn, so the targets give its wheels less grip across their rolling direction than along it. In MuJoCo, whose contact friction is the same in every direction, a skid-steer base turns in place at about a third of the commanded rate; the target declares this.</p><h2 id="steering-bases" tabindex="-1">Steering bases <a class="header-anchor" href="#steering-bases" aria-label="Permalink to &quot;Steering bases&quot;">​</a></h2><p>A tricycle or an Ackermann base steers its front wheels about kingpins. The chassis part states each steered mount&#39;s kingpin axis and how far it turns:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">wheel_mount_front</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  pos</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.15</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">-0.02</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  dir</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  steering</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">axis</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">max_angle_rad</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.6</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>The targets hang the wheel from a light knuckle that turns about that axis, and plan with Smac Hybrid-A* at the base&#39;s minimum turning radius, the wheelbase over the tangent of the steering limit, following the path with MPPI&#39;s Ackermann model. A steering base is not held to a final heading, since it cannot turn in place to correct one, and it cannot <code>Spin</code>.</p><h2 id="omni-bases" tabindex="-1">Omni bases <a class="header-anchor" href="#omni-bases" aria-label="Permalink to &quot;Omni bases&quot;">​</a></h2><p>An omni wheel grips along its rolling direction and slides along its axle. The runtime&#39;s omni drive turns <code>/cmd_vel</code> into each wheel&#39;s speed from its position and rolling direction, and computes the odometry back from the measured wheel speeds. That works for any layout, including the rectangles most four-wheel omni bases are built on, as long as the wheels&#39; rolling directions span the plane; the rule <code>kinematics.omni_wheels_span_the_plane</code> checks that.</p><h2 id="mecanum-bases" tabindex="-1">Mecanum bases <a class="header-anchor" href="#mecanum-bases" aria-label="Permalink to &quot;Mecanum bases&quot;">​</a></h2><p>A mecanum wheel&#39;s rollers let it slide along one diagonal. In Gazebo, each wheel is a sphere that grips along one diagonal and slides along the other. MuJoCo cannot yet model that sliding, so the <code>ros-mujoco-nav2</code> target refuses mecanum and omni bases.</p><p><a href="./../../reference/vocabulary.html#chassis-types">Chassis types</a> in the vocabulary lists the mounts of each type.</p>`,17)])])}const m=t(d,[["render",n]]);export{k as __pageData,m as default};
